  "revision_action": "strengthen",
  "supportive_card_ids": ["C14", "C15", "C03", "C04", "C11", "C10", "C17", "C35", "C38", "C41", "C06", "C08", "C13", "C16", "C18", "C22", "C24", "C28"],
  "contradictory_card_ids": ["C21", "C29", "C31", "C32", "C36", "C42"],
  "prediction_basis_card_ids": ["C14", "C15", "C03", "C04", "C11", "C10", "C17", "C35"],
  "claims": [
    {
      "claim": "The query contains the same saligenin beta2-agonist head group as salbutamol; salbutamol absolute oral bioavailability in fasting subjects was 7.2% and 11.4%, both below the 20% threshold.",
      "card_ids": ["C14", "C15"]
    },
    {
      "claim": "Bambuterol, a related beta2-agonist, has human oral bioavailability of about 10% of the administered dose, below the 20% threshold; L2 dog/rat values are species-specific and do not override the human outcome.",
      "card_ids": ["C03", "C04", "C11", "C35", "C21", "C31"]
    },
    {
      "claim": "Phenylephrine L1 reports poor oral bioavailability; L2 absolute values around 37.5-38% are less transferable because phenylephrine lacks the saligenin head group and is a small hydrophilic alpha agonist, and the same context also reports poor/varied bioavailability with extensive presystemic metabolism.",
      "card_ids": ["C10", "C29", "C38", "C42"]
    },
    {
      "claim": "Epanolol, a related aryloxypropanolamine beta-blocker, has absolute oral bioavailability of 5.85 ± 2.55% with food, below the 20% threshold.",
      "card_ids": ["C17"]
    },
    {
      "claim": "Terfenadine, a high-lipophilicity CYP3A4 substrate, has oral bioavailability below 5% in humans, supporting that high lipophilicity and first-pass metabolism can produce low F, though structural transfer to the query is limited.",
      "card_ids": ["C06", "C08", "C13", "C16", "C18", "C22", "C24", "C28"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C18", "C21", "C22", "C24", "C28", "C29", "C31", "C32", "C35", "C36", "C38", "C41", "C42"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself in the supplied records.",
    "No intravenous reference exposure or matched oral-versus-IV data for the query.",
    "No formulation-specific oral pharmacokinetic data for the query.",
    "Transfer from salbutamol, bambuterol, phenylephrine, and epanolol is structural and pharmacological, not an exact match.",
    "Phenylephrine L2 absolute values around 38% conflict with its qualitative 'poor' L1 outcome and are less transferable due to structural differences."
  ],
  "decision_summary": "The query is a saligenin beta2-agonist closely related to salbutamol and bambuterol, whose measured human oral bioavailability values are below 20%; phenylephrine and epanolol also show poor/low oral bioavailability. L2 records add species-specific high values in dogs/rats and a less transferable phenylephrine absolute estimate near 38%, but the human-relevant, structurally closer evidence supports F < 20%. The physicochemical prior is absorption-unfavorable, and no active evidence supports F >= 20%. Therefore the prediction remains low."
}

